/// Plain-`f64` tail of `ln(1+z)`: `(ln(1+z) − z)/z² = ∑ (−1)ᵏ⁺¹ zᵏ/(k+2)`,
/// low-degree first.  Degree 7 over the exact-`z` cells' range `|z| ≤ 2⁻⁷·⁴⁸`;
/// the truncation past `z⁷`, scaled by `z²`, is `z¹⁰/10 ≤ 2⁻⁷⁸` — far under
/// the fast leg's `2⁻⁶⁶` budget.
const LN1P_Q_COEFFS: [f64; 8] = [
    -0.5,
    0.3333333333333333,
    -0.25,
    0.2,
    -0.16666666666666666,
    0.14285714285714285,
    -0.125,
    0.1111111111111111,
];

/// Plain-`f64` tail of `ln(1+x)` past the exact `x − x²/2`:
/// `f(x) = (ln(1+x) − x + x²/2)/x³ = ∑_{k≥0} (−1)ᵏ xᵏ/(k+3)`, low-degree first.
///
/// Used by the [`log1p`] mid-`|x|` leg `[2⁻⁸, 2⁻⁴)`, where the leading `x − x²/2`
/// is carried to extra precision (one `fma`) so the leg error rides only the
/// `x³·f` correction (gate ∝ `x³`, [`LN1P_WIDE_ZIV_SCALE`]) — far tighter than
/// reusing `ln`'s absolute gate, which over-falls-back where the result is small.
/// Degree 13: the truncation past `x¹³`, scaled by `x³`, is `x¹⁷/19 ≤ 2⁻⁷²` at
/// `|x| = 2⁻⁴` — far under the leg's `≈2⁻⁵²·x³` budget.
const LN1P_F_WIDE: [f64; 14] = [
    0.3333333333333333,
    -0.25,
    0.2,
    -0.16666666666666666,
    0.14285714285714285,
    -0.125,
    0.1111111111111111,
    -0.1,
    0.09090909090909091,
    -0.08333333333333333,
    0.07692307692307693,
    -0.07142857142857142,
    0.06666666666666667,
    -0.0625,
];

/// Correction-scaled Ziv gate for `ln_1p`'s small-`|x|` branch (`|x| < 1/256`):
/// the absolute error bound is `x² · LN1P_SMALL_ZIV_SCALE`.
///
/// Every error in the branch scales with the `x²·Q(x)` correction: the Estrin
/// evaluation of [`LN1P_Q_COEFFS`] (≈4·2⁻⁵⁴ against `|Q| ≈ ½`), the roundings
/// of `x·x` and of the `x²·Q` product (≤2⁻⁵⁴ relative each), and the degree-7
/// truncation (`x⁷/10 ≤ 2⁻⁵⁹` relative to the correction) — together under
/// `2⁻⁵¹·⁴·x²`, so `2⁻⁴⁸` keeps a ~10× margin.  Scaling the gate by `x²` (the
/// old gate was a flat `2⁻⁵⁶` *relative*, sized for the worst `|x| ≈ 2⁻⁸`)
/// drops the straddle odds to `≈2⁻⁴⁵·|x|` — the fallback all but vanishes,
/// where the flat gate fell back on ≈2⁻³·⁵ of random small inputs.
const LN1P_SMALL_ZIV_SCALE: f64 = 3.552713678800501e-15; // 2^-48

/// Ziv gate for `log1p`'s mid-`|x|` leg (`2⁻⁸ ≤ |x| < 2⁻⁴`): an absolute bound
/// `|x|³ · LN1P_WIDE_ZIV_SCALE` on the leg error.
///
/// The leading `x − x²/2` is carried exactly (the `fma` residual joins the low
/// word), so the error is only the `x³·f` correction: the rounding of `x³·f`
/// (≈2⁻⁵³·|f|, `|f| ≤ 0.34`) and the Estrin evaluation of [`LN1P_F_WIDE`]
/// (≈13·2⁻⁵⁴ against `|f|`) — together under `≈2⁻⁵²·x³`, so `2⁻⁵⁰` keeps a ~4×
/// margin.  A dense `[2⁻⁸, 2⁻⁴)` sweep against the `core-math` oracle and the
/// worst-case corpus (`test_log1p_worst_cases`) round bit-exactly.
const LN1P_WIDE_ZIV_SCALE: f64 = 8.881784197001252e-16; // 2^-50

/// Ziv gate for the natural log's fast path, as an absolute error bound.
///
/// The exact-`z` fast leg is good to <2⁻⁶⁶ absolute: the reduction commits no
/// error (`z` is exact, `e·LN2_HI + l1` is exact, the Fast2Sum with `z` is
/// exact), so the budget is the plain-`f64` tail — Estrin evaluation
/// ≈3·2⁻⁵⁴·z² ≤ 2⁻⁶⁷·⁴ at `|z| ≤ 2⁻⁷·⁴⁸`, plus ≈2⁻⁶⁹ each from rounding `z²`,
/// the `z²·Q` product, and the low-word folds, plus 2⁻⁷⁸ truncation and the
/// 2⁻⁹⁶/2⁻⁸⁸ table and `ln 2` splits.  `2⁻⁶³` keeps an 8× margin.  Being
/// absolute, the gate only forces the accurate fallback for `|ln x| ≲ 2⁻¹⁰`,
/// i.e. `x` within ~2⁻¹⁰ of 1.
const LN_ZIV_EPS: f64 = 1.0842021724855044e-19; // 2^-63

/// Ziv gate for `log2`/`log10`, scaled from [`LN_ZIV_EPS`] by `log2(e)` so it
/// bounds the base-e lean leg's slip after the base conversion — for `log10`
/// as `ln_fast(x) · log10(e)`, and for `log2`'s native base-2 leg, whose error
/// sources are the base-e ones scaled by `log2(e)` plus ≲2⁻⁶⁷ of low-word
/// rounding of its own (see the leg in [`log2`]).
const LOG2_ZIV_EPS: f64 = 1.5641377104174595e-19; // 2^-63 · log2(e), rounded up
const LOG10_ZIV_EPS: f64 = 1.0842021724855044e-19; // 2^-63 (≥ 2^-63 · log10(e))

const LOG2_E_HI: f64 = 1.4426950408889634;
const LOG2_E_LO: f64 = 2.0355273740931033e-17;
const LOG10_E_HI: f64 = 0.4342944819032518;
const LOG10_E_LO: f64 = 1.098319650216765e-17;

/// `ln(1 + r)` as a double-double for `|r| ≤ 1/256`, via `ln(1+r) = r · P(r)`.
#[inline]
fn ln_1p_kernel(r: DoubleDouble) -> DoubleDouble {
    let (high, low) = LN1P_P_COEFFS[LN1P_P_COEFFS.len() - 1];
    let mut p = DoubleDouble { high, low };

    for &(high, low) in LN1P_P_COEFFS[..LN1P_P_COEFFS.len() - 1].iter().rev() {
        p = p * r + DoubleDouble { high, low };
    }

    p * r
}

/// Correctly-rounded `ln(1 + x)` for an exact `|x| < 1/256`, anchored at the
/// result.
///
/// `ln(1+x) = x + x²·Q(x)` with `Q(x) = (ln(1+x) − x)/x² = ∑_{k≥0} (−1)ᵏ⁺¹ xᵏ/(k+2)`
/// — the [`LN1P_P_COEFFS`] series shifted down past its leading `1`.  Evaluating
/// only the correction `c = x²·Q(x)` as a double-double keeps its ≈2⁻¹⁰⁴ relative
/// error on the *tiny* `c` (≲2⁻⁹·|x|), so adding the **exact** `x` leaves an
/// absolute error far under ½ ulp of the result.  [`super::double::round_anchored`]
/// then breaks the hardest corpus ties (where `x + c.high` lands on a midpoint) by
/// the sign of the exact sticky tail `c.low`.
#[inline]
fn log1p_small_accurate(x: f64) -> f64 {
    let xd = DoubleDouble { high: x, low: 0.0 };

    // Q(x) as a double-double Horner over LN1P_P_COEFFS[1..] (the P-series minus
    // its leading 1), then c = x²·Q(x).
    let (high, low) = LN1P_P_COEFFS[LN1P_P_COEFFS.len() - 1];
    let mut q = DoubleDouble { high, low };
    for &(high, low) in LN1P_P_COEFFS[1..LN1P_P_COEFFS.len() - 1].iter().rev() {
        q = q * xd + DoubleDouble { high, low };
    }
    let c = (xd * xd) * q;

    // result = round(x + c) with `x` exact: the result-anchored finisher.
    super::double::round_anchored(x, c)
}

/// The small-`|x|` fast leg of [`log1p`] (`2⁻⁵⁴ ≲ |x| < 2⁻⁸`): the exact `x`
/// lead plus the `x²·Q(x)` correction, as the raw pair the
/// [`LN1P_SMALL_ZIV_SCALE`] gate consumes (soundness certified by
/// `ziv_soundness::log1p_small_leg_is_sound`).
#[inline]
fn log1p_small_eval(x: f64) -> DoubleDouble {
    let zz = x * x;
    let tail = zz * crate::poly(x, &LN1P_Q_COEFFS);
    fast_sum(x, tail)
}

/// The mid-`|x|` fast leg of [`log1p`] (`2⁻⁸ ≤ |x| < 2⁻⁴`): the exact
/// `x − x²/2` lead (one `fma`, its residual joining the low word) plus the
/// `x³·f(x)` correction, as the raw pair the [`LN1P_WIDE_ZIV_SCALE`] gate
/// consumes (soundness certified by `ziv_soundness::log1p_wide_leg_is_sound`).
#[inline]
fn log1p_wide_eval(x: f64) -> DoubleDouble {
    let hx = -0.5 * x;
    let high = crate::fma(hx, x, x); // x − x²/2, rounded
    let resid = crate::fma(hx, x, x - high); // exact residual of x − x²/2
    let x3 = (x * x) * x;
    let low = crate::fast_mul_add(x3, crate::poly(x, &LN1P_F_WIDE), resid);
    DoubleDouble { high, low }
}

/// The table fast leg of [`log1p`] (`|x| ≥ 2⁻⁴`), on the exact split
/// `1 + x = s + c`, as the raw pair the [`LN_ZIV_EPS`] gate consumes: reduce
/// `s = 2^e·m` with the exact-`z` cells as for `ln`, then fold the tail `c`
/// into the low word.  With `δ = c·2⁻ᵉ` the true mantissa is `m + δ`, so the
/// true reduced argument is `z + r·δ`; `|δ| ≤ ½ulp(m)` makes `dz = r·δ ≤ 2⁻⁵³`,
/// and its first-order image through ln, `dz/(1+z)`, is `dz·(1 − z)` up to a
/// dropped `dz·z² ≤ 2⁻⁶⁸` — inside the gate's margin (certified by
/// `ziv_soundness::log1p_table_leg_is_sound`).
#[inline]
fn log1p_table_raw(s: f64, c: f64) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce(s);
    let delta = if e > -1000 { c * crate::exp2i(-e) } else { 0.0 };
    let dz = cell.r * delta;
    let dz = crate::fast_mul_add(-dz, z, dz);
    let DoubleDouble { high, low } = ln_exact_assemble(e as f64, cell, z);
    DoubleDouble {
        high,
        low: low + dz,
    }
}

/// Decompose a finite positive `x` into `(e, cell, z)` for the exact-`z` fast
/// leg, against a caller-supplied cell table — the base-e [`LN_CELLS`] or the
/// base-2 [`LOG2_CELLS`], which share the reciprocal lattice (`z` is
/// base-agnostic; only the `l` words differ): `x = 2^e · m` with `m ∈ [1, 2)`,
/// `cell` the 7-bit-indexed [`LnCell`], and `z = cell.r · m − 1` computed
/// **exactly** by one fused multiply-add (the lattice argument on [`LnCell`])
/// — the whole reduction is a table load and an FMA, with no double-double
/// residual to carry.
#[inline]
fn exact_reduce_in(cells: &'static [LnCell; 128], x: f64) -> (i64, &'static LnCell, f64) {
    let (_, Magnitude::Normalized(magnitude)) = normalize(x) else {
        // Callers guarantee a finite positive x.
        unreachable!()
    };

    let e = (magnitude >> EXP_SHIFT) - 1023;
    let j = ((magnitude >> (EXP_SHIFT - 7)) & 127) as usize;
    let m = f64::from_bits((magnitude as u64 & 0x000F_FFFF_FFFF_FFFF) | 0x3FF0_0000_0000_0000);

    let cell = &cells[j];
    (e, cell, crate::fma(cell.r, m, -1.0))
}

/// [`exact_reduce_in`] against the base-e [`LN_CELLS`].
#[inline]
fn ln_exact_reduce(x: f64) -> (i64, &'static LnCell, f64) {
    exact_reduce_in(&LN_CELLS, x)
}

/// [`ln_exact_reduce`] for a `x ≥ 1` (so guaranteed normal and positive): skips
/// the full [`normalize`]'s sign test, `classify`, and subnormal branch for a
/// straight bit-field extract.  Used by the inverse-hyperbolic fast legs
/// ([`ln_dd_fast`], [`ln_fast_scaled`]), whose arguments are all `≥ 1`.
#[inline]
fn ln_exact_reduce_normal(x: f64) -> (i64, &'static LnCell, f64) {
    let bits = x.to_bits();
    let e = (bits >> EXP_SHIFT) as i64 - 1023;
    let j = ((bits >> (EXP_SHIFT - 7)) & 127) as usize;
    let m = f64::from_bits((bits & 0x000F_FFFF_FFFF_FFFF) | 0x3FF0_0000_0000_0000);

    let cell = &LN_CELLS[j];
    (e, cell, crate::fma(cell.r, m, -1.0))
}

/// Assemble `ln(2^e·m) = e·ln2 + (l1 + l2) + ln(1+z)` from an
/// [`ln_exact_reduce`] result, as an **unnormalized** pair: `high` is the
/// correctly-rounded sum of the dominant terms and `low` (≲2⁻¹⁵) carries the
/// rest, good to <2⁻⁶⁶ absolute (see [`LN_ZIV_EPS`]).  The in-file Ziv gates
/// consume this form directly; [`ln_fast`] renormalizes it for outside callers.
///
/// The serial chain is three steps: `e·LN2_HI + l1` is **exact** (both are
/// integer multiples of 2⁻⁴² and `|e·LN2_HI + l1| < 746`, i.e. fewer than 2⁵³
/// multiples), the Fast2Sum with the exact `z` is valid (the generator verifies
/// `|e·LN2_HI + l1|` is zero or ≥ max |z| for every reachable pair — the tight
/// cases `e = 0` and `e = −1` per cell), and the plain-`f64` tail of `ln(1+z)`
/// joins the low word off that path.
#[inline]
fn ln_exact_assemble(e: f64, cell: &LnCell, z: f64) -> DoubleDouble {
    // ln(1+z) − z = z²·Q(z), all plain f64: z is exact, so no residual threads
    // through the polynomial.
    let tail = (z * z) * crate::poly(z, &LN1P_Q_COEFFS);

    let s = fast_sum(crate::fma(e, LN2_HI, cell.l1), z);
    let low = tail + (s.low + cell.l2);
    DoubleDouble {
        high: s.high,
        low: crate::fast_mul_add(e, LN2_LO, low),
    }
}

/// Decompose a finite positive `x` into `(e, i, m·inv − 1)` for the log family.
///
/// `x = 2^e · m` with `m ∈ [1, 2)`; `i` is the 7-bit table index and the returned
/// double-double is `r = m · INV_TABLE[i] − 1 ∈ [−1/256, 1/256]`.
#[inline]
fn log_reduce(x: f64) -> (i64, usize, DoubleDouble) {
    let (_, Magnitude::Normalized(magnitude)) = normalize(x) else {
        // Callers guarantee a finite positive x.
        unreachable!()
    };

    let e = (magnitude >> EXP_SHIFT) - 1023;
    let i = ((magnitude >> (EXP_SHIFT - 7)) & 127) as usize;
    let m = f64::from_bits((magnitude as u64 & 0x000F_FFFF_FFFF_FFFF) | 0x3FF0_0000_0000_0000);

    // r = m·inv − 1 as a double-double.  `m·inv ∈ [≈0.996, 1.004]`, so the high
    // word minus one is exact (Sterbenz).
    let mi = DoubleDouble::from_product(m, INV_TABLE[i]);
    let r = fast_sum(mi.high - 1.0, mi.low);

    (e, i, r)
}

/// The natural logarithm of a finite positive `x ≠ 1`, as a double-double.
#[inline]
pub fn ln_dd(x: f64) -> DoubleDouble {
    // ln(x) = e·ln2 + L_TABLE[i] + ln(1+r).
    let (e, i, r) = log_reduce(x);
    let e = e as f64;

    let e_ln2 = DoubleDouble {
        high: e * LN2_HI,
        low: e * LN2_LO,
    };
    let (high, low) = L_TABLE[i];
    e_ln2 + DoubleDouble { high, low } + ln_1p_kernel(r)
}

/// The exact-`z` fast leg end to end, returning the raw unnormalized pair of
/// [`ln_exact_assemble`] — the form the in-file Ziv gates consume.
#[inline]
fn ln_fast_raw(x: f64) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce(x);
    ln_exact_assemble(e as f64, cell, z)
}

/// Lean natural logarithm of a finite positive `x ≠ 1`, as a double-double.
///
/// The exact-`z` fast leg ([`ln_exact_reduce`] + [`ln_exact_assemble`]), good to
/// <2⁻⁶⁶ absolute — see [`LN_ZIV_EPS`].  The closing Fast2Sum renormalizes the
/// pair for the outside consumers (`pow`, the inverse hyperbolics, `lgamma`);
/// its ordering can only fail when the result nearly cancels (`x` within ~2⁻⁸
/// of 1), where `high` still rounds correctly and every caller's absolute Ziv
/// gate rejects the result regardless.  The callers gate this against an
/// accurate fallback ([`dint::ln_accurate`] for `ln`, [`ln_dd`] for the rest).
#[inline]
pub fn ln_fast(x: f64) -> DoubleDouble {
    let DoubleDouble { high, low } = ln_fast_raw(x);
    fast_sum(high, low)
}

/// Lean natural logarithm of `2^k · x`, as a double-double — [`ln_fast`] with the
/// binary exponent biased by `k`.
///
/// `ln(2^k·x) = (e+k)·ln2 + (l1 + l2) + ln(1+z)`, so the scale folds into the
/// reduction's exponent for free, avoiding a separate `+ k·ln2` double-double add.
/// `(e+k)·LN2_HI` stays exact for `|e+k| ≤ 1074`.  Used by the inverse-hyperbolic
/// large-|x| path (`ln(2|x|)`, `k = 1`).
#[inline]
pub fn ln_fast_scaled(x: f64, k: i64) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce_normal(x);
    let DoubleDouble { high, low } = ln_exact_assemble((e + k) as f64, cell, z);
    fast_sum(high, low)
}

/// Lean `ln(s)` for a finite positive double-double with `s.high` normal, as a
/// raw unnormalized pair (the form the in-file Ziv gates consume — see
/// [`ln_exact_assemble`]).
///
/// `ln(s.high + s.low) = ln(s.high) + ln(1 + s.low/s.high)`.  Rather than form
/// the linear correction `s.low/s.high` with a hardware division, fold `s.low`
/// straight into the exact-`z` reduction the way [`log1p`] folds its tail: with
/// `δ = s.low·2⁻ᵉ` the true mantissa is `m + δ`, so the reduced argument gains
/// `cell.r·δ`, whose image through `ln` is `cell.r·δ·(1 − z)` up to a dropped
/// `cell.r·δ·z² ≲ 2⁻⁶⁷` — inside the callers' gates.  The inverse-hyperbolic
/// callers (`atanh`, and `asinh`/`acosh` via `ln_sqrt_rounded`) pass `s > 1`
/// (`e ≥ 0`); `lgamma`'s reflection passes `|sin πz| ∈ (0, 1]`, where `e < 0`
/// makes `2⁻ᵉ` a *positive* power of two — finite and exact for any normal
/// `s.high` (`e ≥ −1022`).
#[inline]
pub fn ln_dd_fast(s: DoubleDouble) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce_normal(s.high);
    let delta = s.low * crate::exp2i(-e);
    let dz = cell.r * delta;
    let dz = crate::fast_mul_add(-dz, z, dz);
    let DoubleDouble { high, low } = ln_exact_assemble(e as f64, cell, z);
    DoubleDouble {
        high,
        low: low + dz,
    }
}

/// The natural logarithm
#[must_use]
#[inline]
pub fn log(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == 1.0 || x == f64::INFINITY {
        return x - 1.0;
    }

    // Two-step Ziv method.  The lean fast path is correctly rounded unless the
    // true value lies within `LN_ZIV_EPS` of a rounding boundary, in which case
    // the always-correct 128-bit accurate path resolves it.  The raw pair feeds
    // the gate directly — `high + (low ± eps)` needs no renormalization.
    let DoubleDouble { high, low } = ln_fast_raw(x);
    let left = high + (low - LN_ZIV_EPS);
    let right = high + (low + LN_ZIV_EPS);
    if left == right {
        left
    } else {
        super::dint::ln_accurate(x)
    }
}

/// The native base-2 fast leg of [`log2`] over [`LOG2_CELLS`], as the raw
/// unnormalized pair the Ziv gate consumes:
/// `log2(2^e·m) = (e + l1) + z·log2(e) + l2 + z²·Q(z)·log2(e)`,
/// sparing the base-e leg's closing `× log2(e)` double-double multiply and
/// its `e·LN2_LO` low fold — in base 2 the exponent join `e + l1` is exact
/// by the table's 2⁻⁴² grid.  The linear term is no longer exact, so
/// `z·LOG2_E_HI` keeps its FMA residual and the `z·LOG2_E_LO` sliver
/// (≤ 2⁻⁶²·⁹) joins it in the low word; the tail reuses the base-e `Q`,
/// scaled by `LOG2_E_HI` on its way in (the dropped `tail·LOG2_E_LO` is
/// ≤ 2⁻⁷¹).  Budget: the base-e leg's <2⁻⁶⁶ absolute scaled by log2(e),
/// plus ≲2⁻⁶⁷ of new low-word rounding — [`LOG2_ZIV_EPS`] holds with its
/// margin intact (certified by `ziv_soundness::log2_fast_leg_is_sound`).
#[inline]
fn log2_fast_raw(x: f64) -> DoubleDouble {
    let (e, cell, z) = exact_reduce_in(&LOG2_CELLS, x);
    let zl = DoubleDouble::from_product(z, LOG2_E_HI);
    let tail = (z * z) * crate::poly(z, &LN1P_Q_COEFFS);
    let s = fast_sum(e as f64 + cell.l1, zl.high);
    let low = crate::fast_mul_add(
        tail,
        LOG2_E_HI,
        s.low + (cell.l2 + crate::fast_mul_add(z, LOG2_E_LO, zl.low)),
    );
    DoubleDouble { high: s.high, low }
}

/// The base-2 logarithm
#[must_use]
#[inline]
pub fn log2(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == 1.0 || x == f64::INFINITY {
        return x - 1.0;
    }

    // Native base-2 fast leg; on a straddle the 128-bit accurate path
    // resolves it.
    let DoubleDouble { high, low } = log2_fast_raw(x);
    let left = high + (low - LOG2_ZIV_EPS);
    let right = high + (low + LOG2_ZIV_EPS);
    if left == right {
        return left;
    }

    super::dint::log2_accurate(x)
}

/// The base-10 logarithm
#[must_use]
#[inline]
pub fn log10(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == 1.0 || x == f64::INFINITY {
        return x - 1.0;
    }

    // log10(x) = ln(x) · log10(e).  Fast path with a Ziv test, as in `log2`.
    let log10e = DoubleDouble {
        high: LOG10_E_HI,
        low: LOG10_E_LO,
    };
    let DoubleDouble { high, low } = ln_fast_raw(x) * log10e;
    let left = high + (low - LOG10_ZIV_EPS);
    let right = high + (low + LOG10_ZIV_EPS);
    if left == right {
        return left;
    }

    super::dint::log10_accurate(x)
}

/// Compute `ln(1 + x)` accurately, especially for small `x`
#[must_use]
#[inline]
pub fn log1p(x: f64) -> f64 {
    if x.is_nan() || x == 0.0 {
        // Preserve the sign of zero: ln_1p(±0) = ±0.
        return x;
    }
    if x < -1.0 {
        return f64::NAN;
    }
    if x == -1.0 {
        return f64::NEG_INFINITY;
    }
    if x == f64::INFINITY {
        return x;
    }

    // |x| < 2⁻⁵⁴: ln(1+x) = x − x²/2 + … rounds to x itself — even for a
    // power-of-two x the correction `x²/2 < 2⁻¹⁰⁹` sits under a quarter of the
    // downward ulp `2⁻¹⁰⁷` — and computing `x²` here would underflow into a
    // subnormal (a microcode assist on the representation-uniform bench's
    // dominant tiny-|x| draws).  Return x directly.
    if x.abs() < 5.551115123125783e-17 {
        return x;
    }

    // Small |x|: evaluate ln(1+x) = x·P(x) directly.  This avoids the table's
    // `L[i] + ln(1+r)` cancellation, which would cap accuracy when the result is
    // tiny, and `x` is already an exact reduced argument in the kernel's range.
    if x.abs() < 1.0 / 256.0 {
        // Fast path: `x` is exact here, so `ln(1+x) = x + x²·Q(x)` evaluates
        // directly with the shared degree-7 plain-`f64` `Q`, and the `x` lead
        // stays exact in the Fast2Sum.  The Ziv gate scales with the `x²`
        // correction ([`LN1P_SMALL_ZIV_SCALE`]) — every error source does — so
        // the straddle odds shrink with `|x|` and the accurate kernel almost
        // never runs.  When `x²` underflows the gate is 0 and `x` itself is the
        // correctly rounded result (the dropped `−x²/2` is far below ½ ulp).
        let DoubleDouble { high, low } = log1p_small_eval(x);
        let err = LN1P_SMALL_ZIV_SCALE * (x * x);
        let lo = high + (low - err);
        let hi = high + (low + err);
        if lo == hi {
            return lo;
        }

        // Accurate fallback, anchored at the *result*: the `dint` path forms a
        // 128-bit `1 + x` whose window sits at magnitude `1`, leaving only ≈86
        // bits at a tiny result like `x ≈ 2⁻⁴²` — short of the near-½-ulp ties
        // here.  Instead compute only the correction `c = ln(1+x) − x = x²·Q(x)`
        // as a double-double: its ≈2⁻¹⁰⁴ relative error rides the *tiny* `c`, not
        // the result, so `x` (exact) + `c` resolves the rounding.
        return log1p_small_accurate(x);
    }

    // Mid |x| (`2⁻⁸ ≤ |x| < 2⁻⁴`): still evaluate the relative-accurate series
    // rather than the table reduction.  There the result `ln(1+x)` is small
    // (≥ ≈2⁻⁸), where the reduction path's *absolute* gate is coarse relative to
    // the result and forces the accurate fallback on a large fraction of inputs.
    // The series keeps the leading `x − x²/2` exact (one `fma`, its residual
    // joining the low word), so only the `x³·f` correction carries error and the
    // gate scales with `x³` ([`LN1P_WIDE_ZIV_SCALE`]) — the fallback all but
    // vanishes.  (Mirrors CORE-MATH's `|x| < 2⁻⁴` polynomial branch.)
    if x.abs() < 0.0625 {
        let DoubleDouble { high, low } = log1p_wide_eval(x);
        let err = LN1P_WIDE_ZIV_SCALE * ((x * x) * x).abs();
        let lo = high + (low - err);
        let hi = high + (low + err);
        if lo == hi {
            return lo;
        }

        // Accurate fallback: `|x| ≥ 2⁻⁸` keeps the result `≥ ≈2⁻⁸`, well within
        // the `dint` 128-bit `1 + x`'s reach, so the same correctly-rounded path
        // the reduction leg uses resolves the rare straddle.
        let s = 1.0 + x;
        return super::dint::log1p_accurate(s, x - (s - 1.0));
    }

    // Otherwise carry 1 + x exactly as `s + c` (Fast2Sum), so the bits of `x` lost
    // in forming `s` are kept in `c`.  `1 + x` is commutative, so the high word is
    // the same either way; only the residual depends on which operand is larger.
    let s = 1.0 + x;
    let c = if x.abs() <= 1.0 {
        x - (s - 1.0)
    } else {
        1.0 - (s - x)
    };

    // `|x| ≥ 2⁻⁴` keeps `|ln(1+x)| ≥ ln(1 − 2⁻⁴) ≈ 2⁻³·⁹` away from zero, so
    // the same absolute gate as `ln` applies; fall back to the accurate kernel
    // on a straddle.
    let DoubleDouble { high: rh, low: rl } = log1p_table_raw(s, c);
    let lo = rh + (rl - LN_ZIV_EPS);
    let hi = rh + (rl + LN_ZIV_EPS);
    if lo == hi {
        return lo;
    }

    // Accurate fallback: `1 + x = s + c` exactly, so feed that exact sum to the
    // correctly-rounded 128-bit `dint` log (the same path `ln`/`log2`/`log10`
    // use).  This resolves the hard-to-round cases the double-double kernel mis-rounds.
    super::dint::log1p_accurate(s, c)
}

/// `log₂e` as a double-double, the base-2 lift of the `log2p1` legs.
const LOG2_E_DD: DoubleDouble = DoubleDouble {
    high: LOG2_E_HI,
    low: LOG2_E_LO,
};

/// `log₁₀e` as a double-double, the base-10 lift of the `log10p1` legs.
const LOG10_E_DD: DoubleDouble = DoubleDouble {
    high: LOG10_E_HI,
    low: LOG10_E_LO,
};

/// Absolute Ziv gates for the `log2p1`/`log10p1` table legs: [`LN_ZIV_EPS`]
/// lifted by the base constant, widened 1.0625× for the double-double
/// product's own roundings (the product's ≈2⁻¹⁰⁴ relative error stays far
/// below this absolute width across the whole band; certified by
/// `ziv_soundness::log2p1_table_leg_is_sound` / `log10p1_table_leg_is_sound`).
const LOG2P1_TABLE_EPS: f64 = LN_ZIV_EPS * LOG2_E_HI * 1.0625;
const LOG10P1_TABLE_EPS: f64 = LN_ZIV_EPS * LOG10_E_HI * 1.0625;

/// Compute `log₂(1 + x)` accurately, especially for small `x`
///
/// C23's `log2p1`.  The band structure mirrors [`log1p`], every leg lifted by
/// `log₂e`: the small/wide series legs and the exact-split table leg reuse
/// [`log1p`]'s raw kernels, multiply by the double-double `log₂e`, and keep
/// the same relative gates scaled by the constant plus a relative `2⁻¹⁰¹`
/// floor for the product's roundings.  Straddles below `2⁻⁴` take the
/// 128-bit series [`super::dint::log2p1_deep`] — which also absorbs
/// everything below `2⁻⁹⁰⁰`, where the gate arithmetic itself would go
/// subnormal — and the table band falls back to
/// [`super::dint::log2p1_accurate`] on the exact `s + c` split.  The exact
/// cases `log2p1(2ᵏ − 1) = k` (`−53 ≤ k ≤ 53`) pass through the table leg's
/// gate naturally under round-to-nearest, so they need no lookup.
#[must_use]
#[inline]
pub fn log2p1(x: f64) -> f64 {
    if x.is_nan() || x == 0.0 {
        return x; // NaN propagates; ±0 keeps its sign
    }
    if x < -1.0 {
        return f64::NAN;
    }
    if x == -1.0 {
        return f64::NEG_INFINITY;
    }
    if x == f64::INFINITY {
        return x;
    }

    let ax = x.abs();
    if ax < 0.0625 {
        if ax < crate::exp2i(-900) {
            return super::dint::log2p1_deep(x);
        }
        if ax < 1.0 / 256.0 {
            let v = log1p_small_eval(x) * LOG2_E_DD;
            let err = crate::fast_mul_add(
                x * x,
                LN1P_SMALL_ZIV_SCALE * LOG2_E_HI,
                v.high.abs() * crate::exp2i(-101),
            );
            let lo = v.high + (v.low - err);
            let hi = v.high + (v.low + err);
            if lo == hi {
                return lo;
            }
            return super::dint::log2p1_deep(x);
        }
        let v = log1p_wide_eval(x) * LOG2_E_DD;
        let err = crate::fast_mul_add(
            (x * x) * ax,
            LN1P_WIDE_ZIV_SCALE * LOG2_E_HI,
            v.high.abs() * crate::exp2i(-101),
        );
        let lo = v.high + (v.low - err);
        let hi = v.high + (v.low + err);
        if lo == hi {
            return lo;
        }
        return super::dint::log2p1_deep(x);
    }

    let s = 1.0 + x;
    let c = if ax <= 1.0 {
        x - (s - 1.0)
    } else {
        1.0 - (s - x)
    };
    let v = log1p_table_raw(s, c) * LOG2_E_DD;
    let lo = v.high + (v.low - LOG2P1_TABLE_EPS);
    let hi = v.high + (v.low + LOG2P1_TABLE_EPS);
    if lo == hi {
        return lo;
    }
    super::dint::log2p1_accurate(s, c)
}

/// Compute `log₁₀(1 + x)` accurately, especially for small `x`
///
/// C23's `log10p1` — [`log2p1`]'s structure with the base-10 constant, the
/// deep tier [`super::dint::log10p1_deep`], and the accurate tier
/// [`super::dint::log10p1_accurate`].  The exact cases
/// `log10p1(10ⁿ − 1) = n` (`1 ≤ n ≤ 15`) pass through the table leg's gate
/// naturally under round-to-nearest.
#[must_use]
#[inline]
pub fn log10p1(x: f64) -> f64 {
    if x.is_nan() || x == 0.0 {
        return x; // NaN propagates; ±0 keeps its sign
    }
    if x < -1.0 {
        return f64::NAN;
    }
    if x == -1.0 {
        return f64::NEG_INFINITY;
    }
    if x == f64::INFINITY {
        return x;
    }

    let ax = x.abs();
    if ax < 0.0625 {
        if ax < crate::exp2i(-900) {
            return super::dint::log10p1_deep(x);
        }
        if ax < 1.0 / 256.0 {
            let v = log1p_small_eval(x) * LOG10_E_DD;
            let err = crate::fast_mul_add(
                x * x,
                LN1P_SMALL_ZIV_SCALE * LOG10_E_HI,
                v.high.abs() * crate::exp2i(-101),
            );
            let lo = v.high + (v.low - err);
            let hi = v.high + (v.low + err);
            if lo == hi {
                return lo;
            }
            return super::dint::log10p1_deep(x);
        }
        let v = log1p_wide_eval(x) * LOG10_E_DD;
        let err = crate::fast_mul_add(
            (x * x) * ax,
            LN1P_WIDE_ZIV_SCALE * LOG10_E_HI,
            v.high.abs() * crate::exp2i(-101),
        );
        let lo = v.high + (v.low - err);
        let hi = v.high + (v.low + err);
        if lo == hi {
            return lo;
        }
        return super::dint::log10p1_deep(x);
    }

    let s = 1.0 + x;
    let c = if ax <= 1.0 {
        x - (s - 1.0)
    } else {
        1.0 - (s - x)
    };
    let v = log1p_table_raw(s, c) * LOG10_E_DD;
    let lo = v.high + (v.low - LOG10P1_TABLE_EPS);
    let hi = v.high + (v.low + LOG10P1_TABLE_EPS);
    if lo == hi {
        return lo;
    }
    super::dint::log10p1_accurate(s, c)
}

/// MPFR-certified soundness of the log-family fast-leg Ziv gates.  A gate must
/// exceed the leg's true error with margin (here ≥2×), or a confident
/// `lo == hi` could certify a value on the wrong side of a rounding boundary.
/// Run with `--features mpfr`.
#[cfg(all(test, feature = "mpfr"))]
mod ziv_soundness {
    use super::*;
    use rug::Float;

    fn mix(i: u64) -> u64 {
        let mut z = i.wrapping_mul(0x2545_F491_4F6C_DD1D);
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Worst-case `|leg(x) − f(x)| / gate(x)` over `[lo, hi]` vs a 250-bit MPFR
    /// reference `f`, with `leg` the raw pair the Ziv test actually sees and
    /// `gate` its half-width.  A ratio `< 0.5` everywhere certifies the 2×
    /// soundness margin.  Returns `(worst_ratio, worst_x)`.
    fn worst_ratio(
        lo: f64,
        hi: f64,
        n: u64,
        leg: impl Fn(f64) -> DoubleDouble,
        gate: impl Fn(f64) -> f64,
        f: impl Fn(&Float) -> Float,
    ) -> (f64, f64) {
        let (lb, hb) = (lo.to_bits(), hi.to_bits());
        let mut worst = 0.0_f64;
        let mut worst_x = lo;
        for i in 0..n {
            let b = lb + mix(i) % (hb - lb);
            let x = f64::from_bits(b);
            let e = leg(x);
            let got = Float::with_val(250, e.high) + Float::with_val(250, e.low);
            let truth = f(&Float::with_val(250, x));
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / gate(x);
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        (worst, worst_x)
    }

    /// The [`LN_ZIV_EPS`] gate must cover [`ln_fast_raw`]'s true error over the
    /// whole positive domain `ln` feeds it (subnormals included).
    #[test]
    fn ln_fast_leg_is_sound() {
        let (worst, x) = worst_ratio(
            f64::from_bits(1),
            f64::MAX,
            8_000_000,
            ln_fast_raw,
            |_| LN_ZIV_EPS,
            |x| x.clone().ln(),
        );
        println!("ln fast leg: worst |err|/gate = {worst:.4} at x={x:e}");
        assert!(
            worst < 0.5,
            "ln gate covers only {:.2}× the slip at x={x:e}",
            1.0 / worst
        );
    }

    /// The [`LOG2_ZIV_EPS`] gate must cover the native base-2 leg
    /// ([`log2_fast_raw`]) — including its new low-word roundings on top of the
    /// base-e budget scaled by `log2(e)`.
    #[test]
    fn log2_fast_leg_is_sound() {
        let (worst, x) = worst_ratio(
            f64::from_bits(1),
            f64::MAX,
            8_000_000,
            log2_fast_raw,
            |_| LOG2_ZIV_EPS,
            |x| x.clone().log2(),
        );
        println!("log2 fast leg: worst |err|/gate = {worst:.4} at x={x:e}");
        assert!(
            worst < 0.5,
            "log2 gate covers only {:.2}× the slip at x={x:e}",
            1.0 / worst
        );
    }

    /// The [`LOG10_ZIV_EPS`] gate must cover the `log10` leg —
    /// [`ln_fast_raw`]'s slip carried through the `× log10(e)` double-double
    /// multiply, exactly as [`log10`] forms it.
    #[test]
    fn log10_fast_leg_is_sound() {
        let log10e = DoubleDouble {
            high: LOG10_E_HI,
            low: LOG10_E_LO,
        };
        let (worst, x) = worst_ratio(
            f64::from_bits(1),
            f64::MAX,
            8_000_000,
            |x| ln_fast_raw(x) * log10e,
            |_| LOG10_ZIV_EPS,
            |x| x.clone().log10(),
        );
        println!("log10 fast leg: worst |err|/gate = {worst:.4} at x={x:e}");
        assert!(
            worst < 0.5,
            "log10 gate covers only {:.2}× the slip at x={x:e}",
            1.0 / worst
        );
    }

    /// The `x²`-scaled [`LN1P_SMALL_ZIV_SCALE`] gate must cover
    /// [`log1p_small_eval`]'s true error over its band `2⁻⁵⁴ ≲ |x| < 2⁻⁸`,
    /// both signs.
    #[test]
    fn log1p_small_leg_is_sound() {
        let gate = |x: f64| LN1P_SMALL_ZIV_SCALE * (x * x);
        let (lo, hi) = (5.551115123125783e-17, 3.90625e-3);
        let (wp, xp) = worst_ratio(lo, hi, 4_000_000, log1p_small_eval, gate, |x| {
            x.clone().ln_1p()
        });
        let (wn, xn) = worst_ratio(
            lo,
            hi,
            4_000_000,
            |t| log1p_small_eval(-t),
            gate,
            |t| (-t.clone()).ln_1p(),
        );
        println!("log1p small leg: worst |err|/gate = {wp:.4} at x={xp:e}, {wn:.4} at x=-{xn:e}");
        assert!(
            wp < 0.5,
            "log1p small gate covers only {:.2}× the slip at x={xp:e}",
            1.0 / wp
        );
        assert!(
            wn < 0.5,
            "log1p small gate covers only {:.2}× the slip at x=-{xn:e}",
            1.0 / wn
        );
    }

    /// The `|x|³`-scaled [`LN1P_WIDE_ZIV_SCALE`] gate must cover
    /// [`log1p_wide_eval`]'s true error over its band `2⁻⁸ ≤ |x| < 2⁻⁴`, both
    /// signs.
    #[test]
    fn log1p_wide_leg_is_sound() {
        let gate = |x: f64| LN1P_WIDE_ZIV_SCALE * ((x * x) * x);
        let (lo, hi) = (3.90625e-3, 0.0625);
        let (wp, xp) = worst_ratio(lo, hi, 4_000_000, log1p_wide_eval, gate, |x| {
            x.clone().ln_1p()
        });
        let (wn, xn) = worst_ratio(
            lo,
            hi,
            4_000_000,
            |t| log1p_wide_eval(-t),
            gate,
            |t| (-t.clone()).ln_1p(),
        );
        println!("log1p wide leg: worst |err|/gate = {wp:.4} at x={xp:e}, {wn:.4} at x=-{xn:e}");
        assert!(
            wp < 0.5,
            "log1p wide gate covers only {:.2}× the slip at x={xp:e}",
            1.0 / wp
        );
        assert!(
            wn < 0.5,
            "log1p wide gate covers only {:.2}× the slip at x=-{xn:e}",
            1.0 / wn
        );
    }

    /// The [`log1p`] table-leg wrapper: the exact `1 + x = s + c` split feeding
    /// [`log1p_table_raw`], exactly as `log1p` forms it.
    fn log1p_table_leg(x: f64) -> DoubleDouble {
        let s = 1.0 + x;
        let c = if x.abs() <= 1.0 {
            x - (s - 1.0)
        } else {
            1.0 - (s - x)
        };
        log1p_table_raw(s, c)
    }

    /// The [`LN_ZIV_EPS`] gate must cover the table leg's true error over
    /// `|x| ≥ 2⁻⁴` — including the `dz` low-word fold and the deep-cancellation
    /// end `x → −1` (where `e < 0` in the reduction).
    #[test]
    fn log1p_table_leg_is_sound() {
        let (wp, xp) = worst_ratio(
            0.0625,
            f64::MAX,
            4_000_000,
            log1p_table_leg,
            |_| LN_ZIV_EPS,
            |x| x.clone().ln_1p(),
        );
        let (wn, xn) = worst_ratio(
            0.0625,
            f64::from_bits(0x3FEF_FFFF_FFFF_FFFF),
            4_000_000,
            |t| log1p_table_leg(-t),
            |_| LN_ZIV_EPS,
            |t| (-t.clone()).ln_1p(),
        );
        println!("log1p table leg: worst |err|/gate = {wp:.4} at x={xp:e}, {wn:.4} at x=-{xn:e}");
        assert!(
            wp < 0.5,
            "log1p table gate covers only {:.2}× the slip at x={xp:e}",
            1.0 / wp
        );
        assert!(
            wn < 0.5,
            "log1p table gate covers only {:.2}× the slip at x=-{xn:e}",
            1.0 / wn
        );
    }

    /// Both signs of a lifted `log2p1`/`log10p1` leg against its production
    /// gate: the leg and gate closures receive the signed `x` exactly as the
    /// public function forms them.
    fn lifted_leg_cert(
        name: &str,
        (lo, hi): (f64, f64),
        leg: &dyn Fn(f64) -> DoubleDouble,
        gate: &dyn Fn(f64) -> f64,
        fref: &dyn Fn(&Float) -> Float,
    ) {
        let (wp, xp) = worst_ratio(lo, hi, 3_000_000, leg, gate, fref);
        let (wn, xn) = worst_ratio(
            lo,
            hi,
            3_000_000,
            |t| leg(-t),
            |t| gate(-t),
            |t| fref(&-t.clone()),
        );
        println!("{name}: worst |err|/gate = {wp:.4} at x={xp:e}, {wn:.4} at x=-{xn:e}");
        assert!(
            wp < 0.5,
            "{name} gate covers only {:.2}× the slip at x={xp:e}",
            1.0 / wp
        );
        assert!(
            wn < 0.5,
            "{name} gate covers only {:.2}× the slip at x=-{xn:e}",
            1.0 / wn
        );
    }

    /// The lifted small-leg gate (relative `x²` window plus the `2⁻¹⁰¹`
    /// product floor) must cover `log1p_small_eval × log₂e` over the whole
    /// band `[2⁻⁹⁰⁰, 2⁻⁸)` — including below `2⁻⁵⁴`, where `x²` underflows
    /// under the floor.
    #[test]
    fn log2p1_small_leg_is_sound() {
        lifted_leg_cert(
            "log2p1 small leg",
            (crate::exp2i(-900), 3.90625e-3),
            &|x| log1p_small_eval(x) * LOG2_E_DD,
            &|x| {
                let v = log1p_small_eval(x) * LOG2_E_DD;
                crate::fast_mul_add(
                    x * x,
                    LN1P_SMALL_ZIV_SCALE * LOG2_E_HI,
                    v.high.abs() * crate::exp2i(-101),
                )
            },
            &|x| x.clone().log2_1p(),
        );
    }

    /// The lifted wide-leg gate over `[2⁻⁸, 2⁻⁴)`.
    #[test]
    fn log2p1_wide_leg_is_sound() {
        lifted_leg_cert(
            "log2p1 wide leg",
            (3.90625e-3, 0.0625),
            &|x| log1p_wide_eval(x) * LOG2_E_DD,
            &|x| {
                let v = log1p_wide_eval(x) * LOG2_E_DD;
                crate::fast_mul_add(
                    (x * x) * x.abs(),
                    LN1P_WIDE_ZIV_SCALE * LOG2_E_HI,
                    v.high.abs() * crate::exp2i(-101),
                )
            },
            &|x| x.clone().log2_1p(),
        );
    }

    /// The absolute [`LOG2P1_TABLE_EPS`] over `|x| ≥ 2⁻⁴`, both signs, up to
    /// `f64::MAX` and down the deep-cancellation end `x → −1`.
    #[test]
    fn log2p1_table_leg_is_sound() {
        let leg = |x: f64| {
            let s = 1.0 + x;
            let c = if x.abs() <= 1.0 {
                x - (s - 1.0)
            } else {
                1.0 - (s - x)
            };
            log1p_table_raw(s, c) * LOG2_E_DD
        };
        let (wp, xp) = worst_ratio(
            0.0625,
            f64::MAX,
            3_000_000,
            leg,
            |_| LOG2P1_TABLE_EPS,
            |x| x.clone().log2_1p(),
        );
        let (wn, xn) = worst_ratio(
            0.0625,
            f64::from_bits(0x3FEF_FFFF_FFFF_FFFF),
            3_000_000,
            |t| leg(-t),
            |_| LOG2P1_TABLE_EPS,
            |t| (-t.clone()).log2_1p(),
        );
        println!("log2p1 table leg: worst |err|/gate = {wp:.4} at x={xp:e}, {wn:.4} at x=-{xn:e}");
        assert!(wp < 0.5, "covers only {:.2}× at x={xp:e}", 1.0 / wp);
        assert!(wn < 0.5, "covers only {:.2}× at x=-{xn:e}", 1.0 / wn);
    }

    /// [`log10p1`]'s small leg, as [`log2p1_small_leg_is_sound`].
    #[test]
    fn log10p1_small_leg_is_sound() {
        lifted_leg_cert(
            "log10p1 small leg",
            (crate::exp2i(-900), 3.90625e-3),
            &|x| log1p_small_eval(x) * LOG10_E_DD,
            &|x| {
                let v = log1p_small_eval(x) * LOG10_E_DD;
                crate::fast_mul_add(
                    x * x,
                    LN1P_SMALL_ZIV_SCALE * LOG10_E_HI,
                    v.high.abs() * crate::exp2i(-101),
                )
            },
            &|x| x.clone().log10_1p(),
        );
    }

    /// [`log10p1`]'s wide leg, as [`log2p1_wide_leg_is_sound`].
    #[test]
    fn log10p1_wide_leg_is_sound() {
        lifted_leg_cert(
            "log10p1 wide leg",
            (3.90625e-3, 0.0625),
            &|x| log1p_wide_eval(x) * LOG10_E_DD,
            &|x| {
                let v = log1p_wide_eval(x) * LOG10_E_DD;
                crate::fast_mul_add(
                    (x * x) * x.abs(),
                    LN1P_WIDE_ZIV_SCALE * LOG10_E_HI,
                    v.high.abs() * crate::exp2i(-101),
                )
            },
            &|x| x.clone().log10_1p(),
        );
    }

    /// [`log10p1`]'s table leg, as [`log2p1_table_leg_is_sound`].
    #[test]
    fn log10p1_table_leg_is_sound() {
        let leg = |x: f64| {
            let s = 1.0 + x;
            let c = if x.abs() <= 1.0 {
                x - (s - 1.0)
            } else {
                1.0 - (s - x)
            };
            log1p_table_raw(s, c) * LOG10_E_DD
        };
        let (wp, xp) = worst_ratio(
            0.0625,
            f64::MAX,
            3_000_000,
            leg,
            |_| LOG10P1_TABLE_EPS,
            |x| x.clone().log10_1p(),
        );
        let (wn, xn) = worst_ratio(
            0.0625,
            f64::from_bits(0x3FEF_FFFF_FFFF_FFFF),
            3_000_000,
            |t| leg(-t),
            |_| LOG10P1_TABLE_EPS,
            |t| (-t.clone()).log10_1p(),
        );
        println!("log10p1 table leg: worst |err|/gate = {wp:.4} at x={xp:e}, {wn:.4} at x=-{xn:e}");
        assert!(wp < 0.5, "covers only {:.2}× at x={xp:e}", 1.0 / wp);
        assert!(wn < 0.5, "covers only {:.2}× at x=-{xn:e}", 1.0 / wn);
    }

    /// The 128-bit series deep tier must round every draw bit-exactly — it is
    /// the tier that replaces CORE-MATH's small-band exception tables, so it
    /// gets a direct MPFR gate over the whole deep band `(0, 2⁻⁴)`, both
    /// signs, subnormals included.
    #[test]
    fn log2p1_deep_is_correct() {
        for i in 0..1_000_000_u64 {
            let x = f64::from_bits(1 + mix(i) % (0x3fb0_0000_0000_0000 - 1));
            for x in [x, -x] {
                let got = super::super::dint::log2p1_deep(x);
                let want = Float::with_val(150, x).log2_1p().to_f64();
                assert!(
                    got.to_bits() == want.to_bits(),
                    "log2p1_deep({x:e}) = {got:e} ≠ {want:e}"
                );
            }
        }
    }

    /// [`log10p1`]'s deep tier, as [`log2p1_deep_is_correct`].
    #[test]
    fn log10p1_deep_is_correct() {
        for i in 0..1_000_000_u64 {
            let x = f64::from_bits(1 + mix(i) % (0x3fb0_0000_0000_0000 - 1));
            for x in [x, -x] {
                let got = super::super::dint::log10p1_deep(x);
                let want = Float::with_val(150, x).log10_1p().to_f64();
                assert!(
                    got.to_bits() == want.to_bits(),
                    "log10p1_deep({x:e}) = {got:e} ≠ {want:e}"
                );
            }
        }
    }
}
